import { ListItem, Select } from '@umami/react-zen';
import { useState } from 'react';

const valuesPredefined = [
  'One',
  'Two',
  'Three',
  'Four',
  'Five',
  'Six',
  'Seven',
  'Eight',
  'Nine',
  'Ten',
];

export function SelectSearchExample({
  isLoading,
  values = valuesPredefined,
}: {
  isLoading?: boolean;
  values?: string[];
}) {
  const [items, setItems] = useState<string[]>(values);
  const [search, setSearch] = useState<string>('');

  const handleSearch = (search: string) => {
    setSearch(search);
    setItems(
      search ? values.filter(item => item.toLowerCase().includes(search.toLowerCase())) : values,
    );
  };

  const handleOpen = (isOpen: boolean) => {
    if (!isOpen) {
      setSearch('');
      setItems(values);
    }
  };

  return (
    <Select
      label="Select"
      placeholder="Please select an option"
      maxHeight="300px"
      allowSearch
      searchValue={search}
      onSearch={handleSearch}
      onOpenChange={handleOpen}
      isLoading={isLoading}
    >
      {items.map(item => (
        <ListItem key={item} id={item}>
          {item}
        </ListItem>
      ))}
    </Select>
  );
}

import { Column, SearchField, TextField } from '@umami/react-zen';
import { useState } from 'react';

export function SearchDelayExample() {
  const [value, setValue] = useState('abc');

  return (
    <Column gap="4">
      <SearchField delay={1000} onSearch={setValue} />
      <TextField name="search" label="Search value" value={value} isReadOnly={true} />
    </Column>
  );
}

import {
  Form,
  FormButtons,
  FormField,
  FormResetButton,
  FormSubmitButton,
  TextField,
} from '@umami/react-zen';

export function FormValidationExample() {
  const validateAge = (value: number) => {
    if (Number.isNaN(Number(value))) return 'Must enter a number';
    if (value <= 18) return 'You must be older than 18';
    if (value >= 100) return 'Age must be less than 100';
    return true;
  };

  return (
    <Form onSubmit={values => console.log(values)}>
      <FormField name="name" label="Name" rules={{ required: 'Name is required' }}>
        <TextField />
      </FormField>
      <FormField
        name="age"
        label="Age"
        rules={{ required: 'Age is required', validate: validateAge }}
      >
        <TextField />
      </FormField>
      <FormButtons>
        <FormResetButton>Reset</FormResetButton>
        <FormSubmitButton isDisabled={false}>Submit</FormSubmitButton>
      </FormButtons>
    </Form>
  );
}

